    /// <summary>
///     AVA <c>getAVAException</c> method.
/// </summary>
/// <param name="_exception">
///     <c>Exception</c> as type
/// </param>
/// <returns>
///     <c>AVAException</c> as return value
/// </returns>
public static AVAException getAVAException(Exception _exception)
{
    AVAException    retVal;

    switch(_exception)
    {
        case    Exception::Info:
            retVal = AVAException::Info;
            break;

        case    Exception::Warning:
            retVal = AVAException::Warning;
            break;

        case    Exception::Deadlock:
            retVal = AVAException::Deadlock;
            break;

        case    Exception::Error:
            retVal = AVAException::Error;
            break;

        case    Exception::Internal:
            retVal = AVAException::Internal;
            break;

        case    Exception::Break:
            retVal = AVAException::Break;
            break;

        case    Exception::DDEerror:
            retVal = AVAException::DDEerror;
            break;

        case    Exception::Sequence:
            retVal = AVAException::Sequence;
            break;

        case    Exception::Numeric:
            retVal = AVAException::Numeric;
            break;

        case    Exception::CLRError:
            retVal = AVAException::CLRError;
            break;

        case    Exception::CodeAccessSecurity:
            retVal = AVAException::CodeAccessSecurity;
            break;

        case    Exception::UpdateConflict:
            retVal = AVAException::UpdateConflict;
            break;

        case    Exception::UpdateConflictNotRecovered:
            retVal = AVAException::UpdateConflictNotRecovered;
            break;

        case    Exception::DuplicateKeyException:
            retVal = AVAException::DuplicateKeyException;
            break;

        case    Exception::DuplicateKeyExceptionNotRecovered:
            retVal = AVAException::DuplicateKeyExceptionNotRecovered;
            break;

        case    Exception::Timeout:
            retVal = AVAException::Timeout;
            break;

        case    Exception::PassClrObjectAcrossTiers:
            retVal = AVAException::PassClrObjectAcrossTiers;
            break;

        case    Exception::NoValidRunnableCode:
            retVal = AVAException::NoValidRunnableCode;
            break;

        case    Exception::ViewDataSourceValidation:
            retVal = AVAException::ViewDataSourceValidation;
            break;

        case    Exception::SystemMaintenance:
            retVal = AVAException::SystemMaintenance;
            break;

        case    Exception::CompanyAccessViolation:
            retVal = AVAException::CompanyAccessViolation;
            break;

        case    Exception::TransientSqlConnectionError:
            retVal = AVAException::TransientSqlConnectionError;
            break;

        case    Exception::PersistentSqlConnectionError:
            retVal = AVAException::PersistentSqlConnectionError;
            break;

        case    Exception::MaximumRetryCountExceeded:
            retVal = AVAException::MaximumRetryCountExceeded;
            break;

        case    Exception::MethodNotFound:
            retVal = AVAException::MethodNotFound;
            break;

        case    Exception::TypeCast:
            retVal = AVAException::TypeCast;
            break;

        case    Exception::FunctionArgument:
            retVal = AVAException::FunctionArgument;
            break;
    }

    return retVal;
}

/// <summary>
///     AVA <c>infoCheckError</c> method.
/// </summary>
/// <param name="startline">
///     <c>int</c> as type
/// </param>
/// <param name="endline">
///     <c>int</c> as type
/// </param>
/// <param name="checkError">
///     <c>NoYes</c> as type
/// </param>
/// <param name="checkWarning">
///     <c>NoYes</c> as type
/// </param>
/// <param name="checkInfo">
///     <c>NoYes</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
static boolean infoCheckError(  int     startline,
                                int     endline,
                                NoYes   checkError      = NoYes::No,
                                NoYes   checkWarning    = NoYes::No,
                                NoYes   checkInfo       = NoYes::No )
{
    int     ii;
    boolean ret = false;

    for(ii=startline; ii <= endline; ii++)
    {
        if(checkError && infolog.level(ii) == Exception::Error)
        {
            ret = true;
            break;
        }
        if(checkWarning && infolog.level(ii) == Exception::Warning)
        {
            ret = true;
            break;
        }
        if(checkInfo && infolog.level(ii) == Exception::Info)
        {
            ret = true;
            break;
        }
    }
    return ret;
}

/// <summary>
///     AVA <c>seconds2Str</c> method.
/// </summary>
/// <param name="seconds">
///     <c>Int64</c> as type
/// </param>
/// <param name="l_cTrenner">
///     <c>str</c> as type
/// </param>
/// <param name="lShowDay">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>NDX_DayTimeString</c> as return value
/// </returns>
[SysObsolete('Pending removal use NDXHelperCommon.seconds2Str() instead', true)]
static NDX_DayTimeString seconds2Str(   Int64   seconds     = DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()),
                                        str     l_cTrenner  = ':',
                                        boolean lShowDay    = true)
{
    #define.Sec(1)
    #define.Min(60)
    #define.Std(3600)       // 60 * 60
    #define.MaxWert(999 * 24 * 60 * 60) // 999 Tage 24:00:00 Stunden
    #define.Null('0')
    #define.Stunden(1)
    #define.Minuten(2)
    #define.Sekunden(3)
    #define.MaxTage(999)
    #define.SecondsPerDay(86400)  // (24 * 60 * 60)

    str     retwert = '';
    int64   rest, divWert, timeValue;
    int     i;
    int64   tage64 = 0;
    str     cTrenner;

    if (seconds > #MaxWert)
    {
        error("@NDX:NXAMoreThan1000daysNotProvided");   // Die Darstellung von Werten > 1000 Tagen ist nicht vorgesehen!
    }

    rest = seconds;
    if (seconds > #SecondsPerDay && lShowDay)
    {
        // calc No of days and remaining seconds
        tage64  = seconds DIV #SecondsPerDay;
        rest    = seconds MOD #SecondsPerDay;
        if (tage64)
        {
            retwert += strfmt("@NDX:NXANoOfDaysShort", tage64);     // %1T
        }
    }
    // Stunden und Minuten
    for (i = #Stunden; i <= #Sekunden; i++)
    {
        cTrenner = l_cTrenner;
        switch (i)
        {
            case #Stunden:
                timeValue = #Std;
                break;
            case #Minuten:
                timeValue = #Min;
                break;
            default:
                timeValue = #Sec;
                cTrenner  = '';
        }

        if (rest >= timeValue)
        {
            divWert = rest div timeValue;
            rest    = rest mod timeValue;
            if (divWert <= 9)
            {
                retwert += #Null;
            }
            retwert += strfmt("@NDX:NXAP1P2", divWert, cTrenner);    // %1%2
        }
        else
        {
            retWert += strfmt("@NDX:NXAZeroZeroP1", cTrenner);            // 00%1
        }
    }
    return retwert;
}

/// <summary>
///     AVA <c>getEnumValueKCS_TransferTypeFilter</c> method.
/// </summary>
/// <param name="_filterValue">
///     <c>KCS_TransferTypeFilter</c> as type
/// </param>
/// <returns>
///     <c>str</c> as return value
/// </returns>
public static KCS_TransferType getEnumValueKCS_TransferTypeFilter(KCS_TransferTypeFilter _filterValue)
{
    KCS_TransferType    retVal;
    KCS_TransferType    locKCS_TransferTypeDefault;

    locKCS_TransferTypeDefault = KCS_TransferType::PPP;

    switch(_filterValue)
    {
        case KCS_TransferTypeFilter::All:
            retVal = locKCS_TransferTypeDefault;
            break;

        case KCS_TransferTypeFilter::PPP:
            retVal = KCS_TransferType::PPP;
            break;

        case KCS_TransferTypeFilter::FieldWarehouse:
            retVal = KCS_TransferType::FieldWarehouse;
            break;

        case KCS_TransferTypeFilter::Agent:
            retVal = KCS_TransferType::Agent;
            break;

        case KCS_TransferTypeFilter::ExternalProduction:
            retVal = KCS_TransferType::ExternalProduction;
            break;

        default:
            retVal = locKCS_TransferTypeDefault;
    }
    return retVal;
}

