/// <summary>
///     AVA <c>adress2singleLineFormat</c> method.
/// </summary>
/// <param name="_name">
///     <c>str</c> as type
/// </param>
/// <param name="_address">
///     <c>str</c> as type
/// </param>
/// <param name="_seperator">
///     <c>str</c> as type
/// </param>
/// <returns>
///     <c>str</c> as return value
/// </returns>
public static str adress2singleLineFormat(str _name, str _address, str _seperator = ' · ')
{
    #define.DefaultSeperator(' · ')
    #define.DefaultSeperatorIfBlank('   ')
    #define.NewLine('\n')

    str retVal;

    if (_seperator == '')
    {
        _seperator = #DefaultSeperatorIfBlank;
    }

    retVal = _name;

    if(_name && _address)
    {
        retVal = _name + _seperator + _address;
    }
    else if(_address)
    {
        retVal = _address;
    }

    if(retVal)
    {
        retVal = strReplace(retVal, #NewLine, _seperator);
    }

    if(retVal) // remove duplicate sperators
    {
        do
        {
            retVal = strReplace(retVal, _seperator + _seperator, _seperator);
        }
        while (strScan(retVal, _seperator + _seperator, 1, strLen(retVal)));
    }

    if(retVal && strScan(retVal, _seperator, 1, strLen(retVal))) // removing leading or following seperators
    {
        if(strScan(retVal, _seperator, strLen(retVal), -strLen(_seperator)))
        {
            retVal = subStr(retVal, 1, strLen(retVal)-strLen(_seperator));
        }
        if(strScan(retVal, _seperator, 1, strLen(_seperator)))
        {
            retVal = subStr(retVal, strLen(_seperator)+1, strLen(retVal)-strLen(_seperator));
        }
    }
    return retVal;
}

