/// <summary>
///     AVA <c>generateQRCodeImage</c> method.
/// </summary>
/// <param name="_QRCodeContainer">
///     <c>container</c> as type
/// </param>
/// <param name="_strToEncode">
///     <c>AVAQRCodeString</c> as type
/// </param>
/// <returns>
///     <c>AVAQRCodeImage</c> as return value
/// </returns>
public static Image generateQRCodeImage(container _QRCodeContainer, AVAQRCodeString _strToEncode = '')
{
    Image               locImage;
    AVAQRCodeContainer  locQRCodeContainer;

    locQRCodeContainer = _QRCodeContainer;

    if(_strToEncode != '')
    {
        locQRCodeContainer = AVAHelperClass::generateQRCode(_strToEncode);
    }

    if(locQRCodeContainer != conNull())
    {
        locImage = new Image(_QRCodeContainer);
        //locImage.setData(_QRCodeContainer);
        locImage.resize(200, 200, 0);
    }
    return locImage;
}

