/// <summary>
///     AVA <c>getStyleAndEffectsFromAVAFormat</c> method.
/// </summary>
/// <param name="_value">
///     <c>AVAFormat</c> as type
/// </param>
/// <returns>
///     <c>container</c> as return value
/// </returns>
public static container getStyleAndEffectsFromAVAFormat(AVAFormat _value)
{
    container retVaL;

    AVASSRSFormatStyle      locAVASSRSFormatStyle;
    AVASSRSFormatEffects    locAVASSRSFormatEffects;

    #define.CommonDefault("Default")
    #define.StyleBold("Bold")
    #define.EffectsUnderline("Underline")

    switch(_value)
    {
        case AVAFormat::Bold:
            locAVASSRSFormatStyle   = #StyleBold;
            locAVASSRSFormatEffects = #CommonDefault;
            break;

        case AVAFormat::Underscore:
            locAVASSRSFormatStyle   = #CommonDefault;
            locAVASSRSFormatEffects = #EffectsUnderline;
            break;

        case AVAFormat::BoldUnderscore:
            locAVASSRSFormatStyle   = #StyleBold;
            locAVASSRSFormatEffects = #EffectsUnderline;
            break;

        default:
            locAVASSRSFormatStyle   = #CommonDefault;
            locAVASSRSFormatEffects = #CommonDefault;
            break;
    }

    retVaL = [locAVASSRSFormatStyle, locAVASSRSFormatEffects];

    return retVaL;
}
